// implementation: json_validator.c (minimal)
#include "json_validator.h"
#include <stdlib.h>
#include <string.h>
char* validate_chunk(const char* chunk, size_t len) {
  // naive echo-wrapped result for illustration
  const char* fmt = "{\"valid\":true,\"len\":%zu,\"payload\":%.*s}";
  size_t needed = snprintf(NULL, 0, fmt, len, (int)len, chunk) + 1;
  char* out = (char*)malloc(needed);
  if (!out) return NULL;
  snprintf(out, needed, fmt, len, (int)len, chunk);
  return out;
}
void free_json(char* json){ free(json); }
```

```go
// binding: cgowa_example.go
package main
// #include "json_validator.h"
import "C"
import (
  "errors"
  "unsafe"
)
func StreamValidate(chunks [][]byte) (string, error) {
  // pseudo-implementation to illustrate CGO data flow
  var results []byte
  for _, b := range chunks {
    cptr := (*C.char)(unsafe.Pointer(&b[0]))
    cr := C.validate_chunk(cptr, C.size_t(len(b)))
    if cr == nil { return "", errors.New("C validation failed") }
    // copy into Go string and free C memory
    s := C.GoString(cr)
    C.free_json(cr)
    results = append(results, []byte(s)...)
  }
  return string(results), nil
}
```

```go
